 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find matching colored bars on opposite outer edges.
    candidates = []
    for axis in (0, 1):  # 0: bars lie on left/right edges; 1: top/bottom
        n = h if axis == 0 else w
        m = w if axis == 0 else h
        edge0 = [grid[i][0] if axis == 0 else grid[0][i] for i in range(n)]
        edge1 = [grid[i][w-1] if axis == 0 else grid[h-1][i] for i in range(n)]
        runs = []
        for edge in (edge0, edge1):
            colored = [(i, v) for i, v in enumerate(edge) if v != bg]
            if colored:
                color = Counter(v for _, v in colored).most_common(1)[0][0]
                inds = [i for i, v in colored if v == color]
                runs.append((color, min(inds), max(inds)))
            else:
                runs.append(None)
        if runs[0] and runs[1] and runs[0][0] == runs[1][0]:
            candidates.append((axis, runs[0][0], runs))
    if not candidates:
        return [row[:] for row in grid]
    axis, bar_color, runs = candidates[0]

    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] != bar_color]
    if not markers:
        return [row[:] for row in grid]
    ray_color = Counter(v for _, _, v in markers).most_common(1)[0][0]

    # Marker coordinates specify offsets within the nearest edge-bar span.
    offsets = set()
    for r, c, _ in markers:
        p = r if axis == 0 else c
        for _, lo, hi in runs:
            if lo <= p <= hi:
                offsets.add(p - lo)
                break
    if not offsets:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    n = h if axis == 0 else w
    m = w if axis == 0 else h
    for side, (_, lo, hi) in enumerate(runs):
        for off in offsets:
            p = lo + off
            if p > hi:
                continue
            for q in range(m):
                if axis == 0:
                    r, c = p, (q if side == 0 else w - 1 - q)
                else:
                    r, c = (q if side == 0 else h - 1 - q), p
                if grid[r][c] == bar_color:
                    continue
                out[r][c] = 4 if grid[r][c] == ray_color else ray_color
    return out

# A compact sanity check for the active test's inferred geometry.
if __name__ == '__main__':
    g = [[9] + [6]*22 for _ in range(20)]
    for r in range(10, 16):
        g[r][-1] = 9
    g[14][6] = 8
    ans = transform(g)
    assert ans[4][0] == 9 and ans[4][1] == 8 and ans[4][-1] == 8
    assert ans[14][0] == 8 and ans[14][6] == 4 and ans[14][-1] == 9
    print(ans)
